app.MapPost("/api/users",async(HttpContext ctx,Db db,PasswordHasher<AppUser> hasher)=>{var u=await Current(ctx,db);var body=await Body(ctx);await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var s=await db.Load(u.Workspace,c,tx);var policy=new Policy(s,u);J.Require(policy.Flag("manageTeam"),"Team management required");var profileBefore=s.Copy();UserProvisioning.AddProfile(s,policy,body);var memberId=J.S(body,"memberId");J.Require(s.Members.TryGetValue(memberId,out var member)&&J.B(member!,"active",true)&&MasterData.RoleActive(s.Settings,J.S(member,"role")),"Choose an active team profile",400);if(!policy.Owner){var target=s.Settings["rolePermissions"]?[J.S(member,"role")] as JsonObject;J.Require(target is not null&&target.All(x=>x.Value?.ToString()!="true"||policy.Flag(x.Key)),"Only the owner can reset a higher-privilege account");}var email=J.S(member,"email").Trim();J.Require(System.Net.Mail.MailAddress.TryCreate(email,out var parsed)&&parsed.Address.Equals(email,StringComparison.OrdinalIgnoreCase),"Set a valid work email on the team profile first",400);var password=J.S(body,"password");PasswordPolicy.Validate(password,app.Configuration);
 await using(var check=new SqlCommand("SELECT Id,IsOwner,WorkspaceId,MemberId FROM dbo.AppUsers WITH (UPDLOCK,HOLDLOCK) WHERE EmailNormalized=@e",c,tx)){check.Parameters.AddWithValue("@e",email.ToUpperInvariant());await using var r=await check.ExecuteReaderAsync();if(await r.ReadAsync()){J.Require(!r.GetBoolean(1)&&r.GetGuid(2)==u.Workspace&&!r.IsDBNull(3)&&r.GetString(3)==memberId,"This login cannot be reset through team account management");}}
 if(body["profile"] is JsonObject)await db.Save(profileBefore,s,c,tx);var hash=hasher.HashPassword(u,password);await Db.Exec(c,tx,"UPDATE dbo.AppUsers SET Email=@e,EmailNormalized=@en,PasswordHash=@h,MustChangePassword=1,SecurityStamp=NEWID(),Disabled=0,FailedAttempts=0,LockedUntil=NULL WHERE WorkspaceId=@w AND MemberId=@m AND IsOwner=0; IF @@ROWCOUNT=0 INSERT dbo.AppUsers(Id,WorkspaceId,Email,EmailNormalized,PasswordHash,MemberId,IsOwner,Disabled,MustChangePassword,FailedAttempts) VALUES(NEWID(),@w,@e,@en,@h,@m,0,0,1,0)",("@h",hash),("@w",u.Workspace),("@m",memberId),("@e",email),("@en",email.ToUpperInvariant()));await tx.CommitAsync();return Results.Json(new{ok=true});}).RequireAuthorization();
app.MapPost("/api/rpc/{method}",async(string method,HttpContext ctx,Db db)=>{var u=await Current(ctx,db);var args=await Body(ctx);if(args["w"]is not null)J.Require(Guid.TryParse(J.S(args,"w"),out var w)&&w==u.Workspace,"Workspace access denied");await using var c=await db.Open();if(method=="erp_load"){var s=await db.Load(u.Workspace,c);return Results.Json(new Policy(s,u).Visible());}if(method=="erp_amc_status"){await using var reportTx=(SqlTransaction)await c.BeginTransactionAsync();var reportState=await db.Load(u.Workspace,c,reportTx);var week=J.S(args,"week");var report=Amc.Report(reportState,new Policy(reportState,u),week==""?J.Today:J.Day(week));await reportTx.CommitAsync();return Results.Json(report);}if(method=="erp_create_workspace")return Results.Json(new{id=u.Workspace,revision=0});
